<?php
session_start();
ob_start();
require_once __DIR__ . '/../backend/db.php';
require_once __DIR__ . '/../backend/student_login_helper.php';
try { synk_student_login_require_admin($conn); }
catch (DomainException $e) { http_response_code(403); exit('Administrator access is required.'); }
$notice = '';
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST') {
    try {
        if (!synk_student_login_check_csrf($_POST['csrf_token'] ?? null)) throw new DomainException('Refresh the page before reviewing an issue.', 403);
        $id = filter_var($_POST['issue_id'] ?? null, FILTER_VALIDATE_INT, ['options'=>['min_range'=>1]]);
        $note = is_string($_POST['review_note'] ?? null) ? trim($_POST['review_note']) : '';
        synk_student_login_review_issue($conn, (int)$id, $note);
        header('Location: student-login-issues.php?reviewed=1'); exit;
    } catch (Throwable $e) { http_response_code($e instanceof DomainException ? (int)$e->getCode() : 500); $notice = $e instanceof DomainException ? $e->getMessage() : 'Unable to save the review. Please try again.'; }
}
$search = is_string($_GET['search'] ?? null) ? substr(trim($_GET['search']),0,255) : '';
$status = ($_GET['status'] ?? '') === 'reviewed' ? 'reviewed' : 'open';
$page = max(1,(int)($_GET['page'] ?? 1)); $pageSize = 25;
$like = '%'.$search.'%';
$where = 'review_status=? AND (submitted_email LIKE ? OR google_email LIKE ? OR google_name LIKE ?)';
$stmt = $conn->prepare('SELECT COUNT(*) AS total FROM tbl_student_login_issues WHERE '.$where);
$stmt->bind_param('ssss',$status,$like,$like,$like);$stmt->execute();$total=(int)$stmt->get_result()->fetch_assoc()['total'];$stmt->close();
$page = min($page,max(1,(int)ceil($total/$pageSize))); $offset = ($page-1)*$pageSize;
$stmt = $conn->prepare('SELECT * FROM tbl_student_login_issues WHERE '.$where.' ORDER BY last_seen DESC,issue_id DESC LIMIT ? OFFSET ?');
$stmt->bind_param('ssssii',$status,$like,$like,$like,$pageSize,$offset);$stmt->execute();$issues=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$h = static function ($value): string { return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8'); };
?>
