<div class="student-issues-heading mb-4"><div><p class="text-muted small text-uppercase mb-1">Student access</p><h1 class="h4 mb-2">Student Sign-in Issues</h1><p class="text-muted student-issue-help mb-0">Check the entered email against the Google account, then correct the student’s email in the Student Directory. Reviewing an issue records your note.</p></div><a class="btn btn-outline-primary" href="students/directory.php"><i class="bx bx-user-pin me-1" aria-hidden="true"></i>Student Directory</a></div>
<?php if ($notice !== ''): ?><div class="alert alert-danger" role="alert"><?= $h($notice) ?></div><?php elseif (isset($_GET['reviewed'])): ?><div class="alert alert-success" role="status">Review saved. Student records remain available in the Student Directory.</div><?php endif; ?>
<div class="card"><div class="card-body"><form class="student-issue-filters mb-3" method="get"><label class="visually-hidden" for="issue-search">Search email or Google name</label><input class="form-control" type="search" id="issue-search" name="search" placeholder="Search email or Google name" value="<?= $h($search) ?>"><label class="visually-hidden" for="issue-status">Review status</label><select class="form-select" id="issue-status" name="status"><option value="open"<?= $status==='open'?' selected':'' ?>>Needs review</option><option value="reviewed"<?= $status==='reviewed'?' selected':'' ?>>Reviewed</option></select><button class="btn btn-primary" type="submit">Filter</button></form>
<p class="small text-muted">Showing <?= count($issues) ?> of <?= $total ?> issues. Repeated attempts for the same email and reason are grouped together.</p>
<?php if (!$issues): ?><div class="text-center py-5"><i class="bx bx-check-circle fs-1 text-primary" aria-hidden="true"></i><h2 class="h5 mt-3">No <?= $status==='open'?'pending':'reviewed' ?> sign-in issues</h2><p class="text-muted mb-0">Unsuccessful student sign-ins will appear here for review.</p></div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Entered email</th><th>Google account</th><th>Reason / attempts</th><th>Last attempt</th><th>Review</th></tr></thead><tbody>
<?php foreach ($issues as $issue): ?><tr><td class="student-issue-cell"><strong><?= $h($issue['submitted_email']) ?></strong><br><a class="small" href="students/directory.php?search=<?= rawurlencode($issue['google_email'] ?: $issue['submitted_email']) ?>">Search directory</a></td><td class="student-issue-cell"><?php if ($issue['identity_verified']): ?><?= $h($issue['google_email']) ?><br><small class="text-muted"><?= $h($issue['google_name']) ?></small><br><span class="badge bg-label-success mt-1">Google verified</span><?php else: ?><span class="text-muted">Not verified</span><?php endif; ?></td><td class="student-issue-cell"><?= $h(synk_student_login_issue_label($issue['failure_code'])) ?><br><small class="text-muted"><?= (int)$issue['attempt_count'] ?> attempt<?= (int)$issue['attempt_count']===1?'':'s' ?></small></td><td><span class="small"><?= $h($issue['last_seen']) ?></span></td><td class="student-issue-note"><?php if ($status==='open'): ?><form class="student-issue-form" method="post"><input type="hidden" name="csrf_token" value="<?= $h(synk_student_login_csrf()) ?>"><input type="hidden" name="issue_id" value="<?= (int)$issue['issue_id'] ?>"><label class="visually-hidden" for="issue-note-<?= (int)$issue['issue_id'] ?>">Review note</label><textarea class="form-control form-control-sm" id="issue-note-<?= (int)$issue['issue_id'] ?>" name="review_note" maxlength="1000" rows="2" placeholder="Optional review note"><?= $h($issue['review_note']) ?></textarea><button class="btn btn-sm btn-outline-primary align-self-start" type="submit">Mark reviewed</button></form><?php else: ?><span class="badge bg-label-secondary">Reviewed</span><p class="small mt-2 mb-0 student-issue-cell"><?= $h($issue['review_note'] ?: 'No note added') ?></p><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><div class="student-issue-pagination mt-3"><span class="small text-muted">Page <?= $page ?> of <?= max(1,(int)ceil($total/$pageSize)) ?></span><?php foreach (['Previous'=>$page-1,'Next'=>$page+1] as $label=>$target): ?><?php if ($target>=1 && $target<=(int)ceil($total/$pageSize)): ?><a class="btn btn-sm btn-outline-secondary" href="?<?= $h(http_build_query(['search'=>$search,'status'=>$status,'page'=>$target])) ?>"><?= $h($label) ?></a><?php endif; ?><?php endforeach; ?></div><?php endif; ?>
</div></div></div><?php include __DIR__.'/../footer.php'; ?></main></div></div><div class="layout-overlay layout-menu-toggle"></div></div>
